#include <stdint.h>
#include "stm32f103x8.h"
#include "stm32f103c8_gpio_driver.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
#warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void clock_init(){
	//Enable GPIOA clock
	RCC_GPIO_A_CLK_EN();
	//Enable GPIOB clock
	RCC_GPIO_B_CLK_EN();
}

void GPIO_init(){
	GPIO_PinConfig_t PinCfg;

	// PA1 input HighZ Floating input (reset state)
	PinCfg.GPIO_PinNumber = GPIO_PIN_1;
	PinCfg.GPIO_MODE = GPIO_MODE_INPUT_FLO;
	MCAL_GPIO_Init(GPIO_A, &PinCfg);

	// PA13 input HighZ Floating input (reset state)
	PinCfg.GPIO_PinNumber = GPIO_PIN_13;
	PinCfg.GPIO_MODE = GPIO_MODE_INPUT_FLO;
	MCAL_GPIO_Init(GPIO_A, &PinCfg);

	// PB1 output PUSH-PULL Mode
	// 01: output mode, max speed 10 MHz
	// CNF 00: General purpose output push-pull
	PinCfg.GPIO_PinNumber = GPIO_PIN_1;
	PinCfg.GPIO_MODE = GPIO_MODE_OUTPUT_PP;
	PinCfg.GPIO_Output_Speed = GPIO_SPEED_10M;
	MCAL_GPIO_Init(GPIO_B, &PinCfg);

	// PB13 output PUSH-PULL Mode
	// 01: output mode, max speed 10 MHz
	// CNF 00: General purpose output push-pull
	PinCfg.GPIO_PinNumber = GPIO_PIN_13;
	PinCfg.GPIO_MODE = GPIO_MODE_OUTPUT_PP;
	PinCfg.GPIO_Output_Speed = GPIO_SPEED_10M;
	MCAL_GPIO_Init(GPIO_B, &PinCfg);
}

void wait_ms(uint32_t time){
	uint32_t i, j;
	for(i = 0; i < time; i++){
		for(j = 0; j < 255; j++);
	}
}

int main(void)
{
	clock_init();
	GPIO_init();

	while(1){
		// PA1 >>> Connected external PUR
		if(MCAL_GPIO_ReadPin(GPIO_A, GPIO_PIN_1) == 0) //press
		{
			MCAL_GPIO_TogglePin(GPIO_B, GPIO_PIN_1);
			while(MCAL_GPIO_ReadPin(GPIO_A, GPIO_PIN_1) == 0); // single
		}

		// PA13 >>> Connected external PDR
		if(MCAL_GPIO_ReadPin(GPIO_A, GPIO_PIN_13) == 0) //press
		{
			MCAL_GPIO_TogglePin(GPIO_B, GPIO_PIN_13);
		}
		wait_ms(1);
	}

}
